.chat-layout {
    display: grid;
    grid-template-columns: 20% 1fr;
    height: 100vh;
    overflow: hidden;
}

.chat-layout.thread-open {
    grid-template-columns: 20% 1fr 25%;
}

.chat-sidebar {
    border-right: 1px solid #dee2e6;
    overflow-y: auto;
    background-color: #2c2f33;
    color: #fff;
}

.chat-main {
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.chat-thread {
    border-left: 1px solid #dee2e6;
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
}

